CREATE TABLE IF NOT EXISTS account_settings(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, history_enabled INTEGER DEFAULT 1, message_policy TEXT DEFAULT 'requests', push_messages INTEGER DEFAULT 1, push_replies INTEGER DEFAULT 1, push_uploads INTEGER DEFAULT 1, mute_until INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS watch_history(user_id TEXT REFERENCES users(id) ON DELETE CASCADE, video_id TEXT REFERENCES videos(id) ON DELETE CASCADE, position REAL DEFAULT 0, watched_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,video_id));
CREATE INDEX IF NOT EXISTS history_recent ON watch_history(user_id,watched_at DESC);
CREATE TABLE IF NOT EXISTS libraries(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT CHECK(kind IN ('collection','playlist')), name TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS library_items(library_id TEXT REFERENCES libraries(id) ON DELETE CASCADE, video_id TEXT REFERENCES videos(id) ON DELETE CASCADE, position INTEGER NOT NULL, PRIMARY KEY(library_id,video_id));
CREATE TABLE IF NOT EXISTS chat_pairs(a TEXT REFERENCES users(id) ON DELETE CASCADE, b TEXT REFERENCES users(id) ON DELETE CASCADE, accepted INTEGER DEFAULT 0, muted_by_a INTEGER DEFAULT 0, muted_by_b INTEGER DEFAULT 0, PRIMARY KEY(a,b));
CREATE INDEX IF NOT EXISTS messages_thread ON messages(sender_id,recipient_id,created_at);
CREATE TABLE IF NOT EXISTS push_subscriptions(endpoint TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, keys_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS push_queue(id INTEGER PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, actor_id TEXT REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, video_id TEXT REFERENCES videos(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, attempts INTEGER DEFAULT 0, next_at INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS voiceovers(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, location TEXT NOT NULL, duration REAL NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
